 const capabilityLabels={'organization.read':'Empresa · consultar','organization.write':'Empresa · editar','organization.transfer':'Empresa · transferir propriedade','organization.close':'Empresa · solicitar encerramento','team.read':'Equipe · consultar','team.invite':'Equipe · convidar','team.manage':'Equipe · gerenciar acesso','store.read':'Lojas · consultar','store.connect':'Lojas · conectar','billing.read':'Assinatura · consultar','billing.manage':'Assinatura · gerenciar','audit.read':'Histórico · consultar','dtf.read':'Estampas DTF · consultar','dtf.write':'Estampas DTF · operar','ads.read':'Anúncios · consultar','reports.read':'Relatórios · consultar','orders.read':'Pedidos · consultar','orders.write':'Pedidos · operar','finance.read':'Financeiro · consultar','finance.write':'Financeiro · editar','production.read':'Produção · consultar','production.write':'Produção · operar','returns.read':'Devoluções · consultar','returns.write':'Devoluções · operar','bank.read':'Banco · consultar','bank.write':'Banco · conciliar','ai.read':'IA · consultar','ai.write':'IA · operar','costs.read':'Custos · consultar','costs.write':'Custos · editar','catalog.read':'Catálogo · consultar','catalog.write':'Catálogo · editar','automation.read':'Automações · consultar','automation.write':'Automações · operar'};
 function allowedCapabilities(role){return Array.isArray(data?.role_capabilities?.[role])?data.role_capabilities[role].filter(cap=>typeof cap==='string'&&has(cap)):[];}
 function capabilityOptions(role,selected){const chosen=new Set(selected||data?.role_defaults?.[role]||[]);return allowedCapabilities(role).map(cap=>'<label class="ca-check"><input name="capabilities" type="checkbox" value="'+esc(cap)+'"'+(chosen.has(cap)?' checked':'')+'><span>'+esc(capabilityLabels[cap]||cap)+'</span></label>').join('')||'<p>Nenhuma permissão delegável disponível para este papel.</p>';}
 function capabilityFields(role,selected=null){const initial=selected||data?.role_defaults?.[role]||[];return '<fieldset class="ca-capabilities" data-capability-picker data-initial-role="'+esc(role)+'" data-initial-capabilities="'+esc(JSON.stringify(initial))+'"><legend>Permissões deste papel</legend><p>O papel limita as opções; selecione o acesso que esta pessoa deve receber. As lojas abaixo limitam onde poderá atuar.</p><div data-capability-options>'+capabilityOptions(role,initial)+'</div></fieldset>';}
 function refreshCapabilityPicker(formNode,reset=false){const picker=formNode.querySelector('[data-capability-picker]');if(!picker)return;const role=value(formNode,'role');let selected=null;if(reset&&role===picker.dataset.initialRole)try{selected=JSON.parse(picker.dataset.initialCapabilities);}catch{}picker.querySelector('[data-capability-options]').innerHTML=capabilityOptions(role,selected);}
