  return title('Aceite o convite','Entre com o e-mail exato da pessoa convidada e confirme o acesso.')+form('invitation','/api/account/invitations/accept',field('token','Código do convite',{type:'password',value:token,maxlength:512}),f=>({token:raw(f,'token'),confirmed:confirmed(f)}),{label:'Aceitar convite',confirm:'Conferi a empresa, a identidade da minha conta e desejo aceitar este acesso.',after:r=>{if(r.accepted!==true)throw Error();go('/companies/'+encodeURIComponent(r.organization_id)+'/settings',{force:true});}})+link('/account/login','Entrar na conta correta');
