 function recordList(values){return rows(values,row=>'<div class="ca-row"><div><strong>'+esc(row.action||row.kind||row.state||'Evento registrado')+'</strong><small>'+esc(stamp(row.created_at||row.at))+'</small></div><span>'+esc(row.result||states[row.state]||'Registrado')+'</span></div>');}
